  for ( let i = 0; i < N; i++ ) if ( X[i]|0 ) pc++;
  const pcp = pc+1, pcm = pc-1;
  let xpp = 0, xpm = 0;
  for ( let i = 0; i < N; i++) {
    xpp = ((xpp<<1) + X[i]) % pcp;
    xpm = ((xpm<<1) + X[i]) % pcm;
