      if(Amax == -1){
        Amax = N;
      }

      Btotal[0] = 0;
      B[0] = sc.nextInt();
      for(int i = 1; i < M+1; i++){
        if(i < M){
          B[i] = sc.nextInt();
        }
        if(i > 0){
          Btotal[i] = Btotal[i-1] + B[i-1];
          if(Bmax == -1 && Btotal[i] > K){
            Bmax = i-1;
          }
        }
      }
      if(Bmax == -1){
        Bmax = M;
      }

      // 全部読み切れるか
      int result = 0;
      if(Atotal[N] + Btotal[M] <= K){
        result = N+M;
      }else if(Amax == 0 && Bmax == 0){
        // 1冊も読めないか
        result = 0;
      }else{
        long totalTime = 0;
        int totalMax = 0;
        if(Amax > Bmax){
          totalMax = Amax;
        }else{
          totalMax = Bmax;
        }

        for(int i = 0; i <= Amax; i++){
          for(int j = totalMax - i; j <= Bmax; j++){
            totalTime = Atotal[i] + Btotal[j];
            if(totalTime <= K){
              //System.out.println(i + " " + j + " " + totalTime);

              int max = i+j;
              if(totalMax < max){
                totalMax = max;
              }
            }else{
              break;
            }
          }
        }
        result = totalMax;
      }

      // 出力
      //System.out.println(Amax);
      //System.out.println(Bmax);
      System.out.println(result);
    }


}

