    power[K-1-child[0]]--;

    for (int i = 1; i < N; i++) {
      if (child[i] > 0) {
        power[K-2]++;
        power[K-2-child[i]]--;
      }
    }

    //System.out.println(Arrays.toString(power));

    int num = 0;
    for (int i = K; i >=0; i--) {
      num += power[i];
      power[i] = num;
    }

    long ans = 1;
    for (int i = 2; i <= K; i++) {
      while (power[i]-- > 0) {
        ans *= i;
        ans %= 1_000_000_007;
      }
    }

    //System.out.println(Arrays.toString(child));
    //System.out.println(Arrays.toString(power));
    System.out.println(ans);
  }
