package main

import "fmt"

var par []int

func root(x int) int {
	if par[x] == x {
		return x
	}
	par[x] = root(par[x])
	return par[x]
}

func unite(x, y int) {
	rx := root(x)
	ry := root(y)
	if rx != ry {
		par[rx] = ry
	}
}

func same(x, y int) bool {
	return root(x) == root(y)
}

func newUnionFind(n int) {
	par = make([]int, n)
	for i := range par {
		par[i] = i
	}
}

func main() {
	var n, m int
	fmt.Scan(&n, &m)
	ps := make([]int, n)
	for i := range ps {
		fmt.Scan(&ps[i])
		ps[i]--
	}
	newUnionFind(n)

	for i := 0; i < m; i++ {
		var x, y int
		fmt.Scan(&x, &y)
		unite(x-1, y-1)
	}

	var cnt int
	for i := 0; i < n; i++ {
		if same(i, ps[i]) {
			cnt++
		}
	}

	fmt.Println(cnt)
}

