			long count = 9;

			var digitList = new List<int>();
			digitList.Add(0);
			digitList.Add(1);

			while(true)
			{
				var digitListCount = digitList.Count;

				var isLunlun = true;

				for(int i = 0; i < digitList.Count - 1; i++)
				{
					if(Math.Abs(digitList[i] - digitList[i + 1]) > 1)
					{
						isLunlun = false;

						if(digitList[i] > digitList[i + 1])
						{
							for (int j = 0; j <= i; j++)
							{
								digitList[j] = 0;
							}

							for (int j = i + 1; j < digitListCount; j++)
							{
								if (digitList[j] != 9)
								{
									digitList[j]++;
									break;
								}
								else
								{
									digitList[j] = 0;
								}
							}
							if (digitList.All(value => value == 0))
							{
								digitList.Add(1);
							}
						}
						else
						{
							digitList[i] = digitList[i + 1] - 1;
							for(int j = i - 1; j >= 0; j--)
							{
								if(digitList[j + 1] > 0)
								{
									digitList[j] = digitList[j + 1] - 1;
								}
								else
								{
									digitList[j] = 0;
								}
							}
						}


						break;
					}
				}

