                  arr[a] = temp++;
               temp = 1;
               for(int a=right-1; a > i; a--)
                  arr[a] = temp++;
               arr[i] = Math.max(arr[i-1],arr[i+1])+1;
            }
         for(int i=0; i <= N; i++)
            if(arr[i] == 0)
            {
               int dex = i-1;
               while(dex >= 0 && arr[dex] < 0)
               {
                  arr[dex] = arr[dex+1]+1;
                  dex--;
               }
               dex = i+1;
               while(dex <= N && arr[dex] < 0)
               {
                  arr[dex] = arr[dex-1]+1;
                  dex++;
               }
            }
         long res = 0L;
         for(int x: arr)
            res += x;
         System.out.println(res);
      }
   }

