import java.util.*;

class Main {

  public static final int mod = 1000000007;
  public static final int fmax = 200005;
  public static long fac[] = new long[fmax];
  public static long inv[] = new long[fmax];
  public static long finv[] = new long[fmax];

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long n = Long.parseLong(sc.next());
    long a = Long.parseLong(sc.next());
    long b = Long.parseLong(sc.next());

    if(n==2 & a==1 & b==2){
      System.out.println("0");
      return;
    }

    NCRinit();

    long ap = n % mod;
    long bp = n % mod;

    for(long i=1; i<=a-1; i++){
      ap *= (n-i);
      ap %= mod;
    }
    for(long i=1; i<=b-1; i++){
      bp *= (n-i);
      bp %= mod;
    }

    for(int i=1; i<=a; i++){
      ap *= inv[i];
      ap %= mod;
    }
    for(int i=1; i<=b; i++){
      bp *= inv[i];
      bp %= mod;
    }

    long ans = modpow(2, (int)n);
    ans %= mod;

    ans -= 1L;
    ans %= mod;
    if(ans<0) ans += mod;
    ans -= ap;
    ans %= mod;
    if(ans<0) ans += mod;
    ans -= bp;
    ans %= mod;
    if(ans<0) ans += mod;

    System.out.println(ans);

  }

  // a^n mod を計算する
  public static long modpow(long x, int n) {
      long ret = 1;
      while (n > 0) {
          if ((n & 1) == 1) {
              ret = (ret * x)%mod;
          }
          x = (x * x)%mod;
          n >>= 1;
      }
      return ret;
  }

  // テーブルを作る前処理
  public static void NCRinit() {
    fac[0] = 1;
    fac[1] = 1;
    finv[0] = 1;
    finv[1] = 1;
    inv[0] = 1;
    inv[1] = 1;
    for (int i = 2; i < fmax; i++){
      fac[i] = fac[i - 1] * i % mod;
      inv[i] = mod - inv[mod%i] * (mod / i) % mod;
      finv[i] = finv[i - 1] * inv[i] % mod;
    }
  }

  // 二項係数計算
  public static long ncr(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
  }

}

import java.util.*;
public class Main {

  public static void main(String[] args) { 
      Scanner sc = new Scanner(System.in);
      int n = sc.nextInt();
      int m = sc.nextInt();
      int[] p = new int[n+1];
      Map<Integer, List<Integer>> graph = new HashMap<>();
      for(int i = 1; i <= n; i++){
        p[i] = sc.nextInt();
        graph.put(i, new ArrayList<>());
      }

      for(int i = 0; i < m; i++) {
        int x = sc.nextInt();
        int y = sc.nextInt();
        graph.get(x).add(y);
        graph.get(y).add(x);
      }

      ArrayList<Set<Integer>> groups = new ArrayList<>();
      boolean[] visited = new boolean[n+1];
      for(int i = 1; i <= n; i++) {
        if(visited[i]) continue;
        Set<Integer> group = new HashSet<>();
        group.add(i);
        dfs(graph, visited, group, i);
        groups.add(group);
      }

      int cnt = 0;
      for(Set<Integer> group : groups) {
        for(int node : group) {
          if(group.contains(p[node])) cnt++;
        }
      }

      System.out.println(cnt);
  }

  private static void dfs(Map<Integer, List<Integer>> graph, boolean[] visited, Set<Integer> group, int curNode) {
    for(int adj : graph.get(curNode)) {
      if(!visited[adj]) {
        visited[adj] = true;
        group.add(adj);
        dfs(graph, visited, group, adj);
      }
    }
  }
}

