        scanf("%ld", &A[i]);
    }
    for(int i=0;i<N;i++){
        scanf("%ld", &B[i]);
    }

    //A-Bが負になるもの(勉強足りない)ものの差の総和を格納する
    long long D=0;
    int d=0; //Dの要素数

    //A-Bが正になるもの(足りてる)を格納する
    long* P;
    NEW(P,N);
    int p=0; //Pの要素数

    for(int i=0;i<N;i++){
        if(A[i]<B[i]){
            D+=(-A[i]+B[i]);
            d++;
        }
        else if(A[i]>B[i]){
            P[p]=A[i]-B[i];
            p++;
        }
    }

