package main

import "fmt"

const N = 105
const K = 1e5+5
const MOD = 1e9+7
var a [N]int
var prefixSum [K]int

func rangeSum (i, j int) int {
  return (prefixSum[j] - prefixSum[i] + MOD) % MOD
}

func max(a, b int) int {
  if a > b {
    return a
  } else {
    return b
  }
}

func main() {
  var n, k int
  fmt.Scanf("%d %d", &n, &k)
  for i := 1; i <= n; i++ {
    fmt.Scanf("%d", &a[i])
  }
