	ss := L / N
	st := L / M
	m := make(map[int]byte)
	for i := 0; i < N; i++ {
		m[i*ss] = S[i]
	}
	for i := 0; i < M; i++ {
		idx := i * st
		v, ok := m[idx]
		if ok && v != T[i] {
			out(-1)
			return
		}
	}

	out(L)

}

