use proconio::input;

fn main() {
    input! {
        t: String,
    }
    let chars: Vec<_> = t.chars().collect();
    let mut questions = Vec::new();

    if chars.len() > 1 && chars.first().unwrap() == &'?' {
        match chars[1] {
            'P' => questions.push('D'),
            'D' | '?' => questions.push('P'),
            _ => unreachable!(),
        }
    } else if chars.len() == 1 && chars.first().unwrap() == &'?' {
        questions.push('D')
    }

    for window in chars.windows(3) {
        let (prev, now, next) = (window[0], window[1], window[2]);
        if now == '?' {
            match prev {
                'P' | '?' => questions.push('D'),
                'D' => match next {
                    'D' | '?' => questions.push('P'),
                    'P' => questions.push('D'),
                    _ => unreachable!(),
                },
                _ => unreachable!(),
            }
        }
    }

    if chars.last().unwrap() == &'?' {
        questions.push('D');
    }

    let mut result: Vec<_> = Vec::new();
    questions.reverse();
    for c in chars {
        match c {
            'P' => result.push('P'),
            'D' => result.push('D'),
            '?' => result.push(questions.pop().unwrap()),
            _ => unreachable!(),
        }
    }
    println!("{}", result.into_iter().collect::<String>());
}

