		}
		if X[i] == '1' {
			sum0 = modadd(sum0, val0[i], cnt-1)
		}
	}
	for i := N - 1; i >= 0; i-- {
		if i == N-1 {
			val1[i] = 1
		} else {
			val1[i] = 2 * val1[i+1] % (cnt + 1)
		}
		if X[i] == '1' {
			sum1 = modadd(sum1, val1[i], cnt+1)
		}
	}

	for i := 0; i < N; i++ {
		if X[i] == '0' {
			// X(i)分足す
			sum := modadd(sum1, val1[i], cnt+1)
			fmt.Printf("%d\n", pops(sum, cnt+1))
		} else {
			// X(i)分引く
			sum := modadd(sum0, -val0[i], cnt-1)
			fmt.Printf("%d\n", pops(sum, cnt-1))
		}
	}
}

// マイナスのmodに注意
func modadd(a, b, mod int64) int64 {
	var rtn int64 = 0
	if a+b < 0 {
		rtn = (a + b + mod) % mod
	} else {
		rtn = (a + b) % mod
	}
	return rtn
}

// f(num1)→f(num2)→...→0とする
func pops(num, mod int64) int64 {
	if mod == 1 {
		return 1
	}

	var ans int64 = 1
	for num != 0 {
		var cnt int64 = 0
		for i := 0; (1 << i) <= num; i++ {
			if num&(1<<i) != 0 {
				cnt++
			}
		}
		if cnt != 0 {
			num %= cnt
		}
		ans++
		if cnt == 0 {
			break
		}
	}
	return ans
}

func popcount(n uint64) int {
	return bits.OnesCount64(n)
}

