#include <stdio.h>

typedef struct {
	long long key, x, l;
} data;

void merge_sort(data x[], int n)
{
	static data y[100001] = {};
	if (n == 1) return;
	merge_sort(&(x[0]), n/2);
	merge_sort(&(x[n/2]), (n+1)/2);

	int i, p, q;
	for (i = 0, p = 0, q = n/2; i < n; i++) {
		if (p >= n/2) y[i] = x[q++];
		else if (q >= n) y[i] = x[p++];
		else y[i] = (x[p].key < x[q].key)? x[p++]: x[q++];
	}
	for (i = 0; i < n; i++) x[i] = y[i];
}

int main()
{
	int i, N;
	long long X[100001], L[100001];
	scanf("%d", &N);
	for (i = 0; i < N; i++) scanf("%lld %lld", &(X[i]), &(L[i]));

	data arm[100001];
	for (i = 0; i < N; i++) {
		arm[i].key = X[i] + L[i];
		arm[i].x = X[i];
		arm[i].l = L[i];
	}
	merge_sort(arm, N);

	int ans[100001] = {0, 1}, lb, ub, j;
	for (i = 1; i < N; i++) {
		for (lb = -1, ub = i - 1; lb < ub; ) {
			j = (lb + ub + 1) / 2;
			if (arm[j].x + arm[j].l <= arm[i].x - arm[i].l) lb = j;
			else ub = j - 1;
		}
		if (ans[lb+1] + 1 > ans[i]) ans[i+1] = ans[lb+1] + 1;
		else ans[i+1] = ans[i];
	}

	printf("%d\n", ans[N]);
	fflush(stdout);
	return 0;
}

