            int x = sc.nextInt();
            int l = sc.nextInt();
            li.add(x);
            map.put(x,l);
        }
        Collections.sort(li);
        int i = 0;
        int left = 0;
        int right = 0;
        for(int v: li){
            if(i == 0){
                left = v-map.get(v);
                right = v+map.get(v);
                ans++;
                //System.out.println(left+" "+right);
            }else{
                int nl = v-map.get(v);
                int nr = v+map.get(v);
