                if(nl-right >= 0){
                    ans++;
                    left = nl;
                    right = nr;
                }else if(nl-right < 0 && nr-right >= 0){
                    continue;
                }else if(nl-right < 0 && nr-right < 0){
                    right = nr;
                }
            }
            i++;
        }
        System.out.println(ans);
