using System.Numerics;
using System.Linq;
using System.Collections.Generic;
class ProgramD
    {
        static void Main(string[] args)
        {

            //入力
            string[] input = Console.ReadLine().Split(' ');
            long n = long.Parse(input[0]);
            long a = long.Parse(input[1]);
            long b = long.Parse(input[2]);

            long MOD = 1000000000 + 7;



            //まずは総和を計算
            //繰り返し二乗法を使う方法
            long ans = modpow(2,n,MOD);


            if(n/2 < a)
                 a = n - a;

            if(n/2 < b)
                 b = n - b;

            long a_sum = 1;
            long b_sum = 1;
            long a_sum_u = 1;
            long b_sum_u = 1;

            //分子の方をかける
            for(long i = 0;i < a;i++)
            {
                    a_sum *= n - i;
                    a_sum %= MOD;
            }

            //分母の方を割る
            for(long i = 0;i < a;i++)
            {
               a_sum_u *= i + 1;
               a_sum_u %= MOD;
            }

            //nCaを求める
            a_sum = a_sum * modpow(a_sum_u,MOD-2,MOD);
            a_sum %= MOD;

            //分子の方をかける
            for(long i = 0;i < b;i++)
            {
                    b_sum *= n - i;
                    b_sum %= MOD;
            }

            //分母の方を割る
            for(long i = 0;i < b;i++)
            {
                b_sum_u *= i + 1;
                b_sum_u %= MOD;
            }

            //nCbを求める
            b_sum = b_sum * modpow(b_sum_u,MOD-2,MOD);
            b_sum %= MOD;


            //最初の数からa,bのケースを引く
            ans -= a_sum;
            ans -= b_sum;
            ans -= 1;
            //最後に割る
            ans %= MOD;

            //負のときは絶対値を戻す
            if(ans < 0)
               ans = MOD - Math.Abs(ans);

            //出力
            Console.WriteLine(ans);

        }

        //繰り返し二乗法で求める
        static long modpow(long a, long n,long MOD)
        {
            if(n == 0)
                return 1;
            if(n % 2 == 0)
            {
                long temp = modpow(a, n/2, MOD);
                return temp*temp % MOD;
            }

            return a * modpow(a,n-1,MOD) % MOD;
        }
    }

