        int n = sc.nextInt();
        String ss = sc.next();
        int t = 0;
        for(int i=0; i<n; i++){
            char c = ss.charAt(i);
            i++;
            if(i==n){
                t++;
                break;
            }
            while(ss.charAt(i)==c){
                i++;
                if(i==n){
                    t++;
                    break;
                }
            }
            if(i==n){
                break;
            }
            i--;
            t++;
            }
