  scanf("%*c%s",x);
  for(i=0;i<n;i++){
    if(x[i]=='1')
      count++;
  }
  int popcount[200002];
  popcount[0]=0;
  for(i=1;i<200001;i++){
    int temp=i,check=0;
    while(temp!=0){
      if(temp%2==1)
        check++;
      temp/=2;
    }
    popcount[i]=popcount[i%check]+1;
  }
  int mod[n][2];
  int num[2]={0,0};
  for(i=n-1;i>=0;i--){
    if(i==n-1){
      mod[n-1][0]=1;
      mod[n-1][1]=1;
    }
    else{
      mod[i][0]=(2*mod[i+1][0])%(count+1);
      if(count>1)
        mod[i][1]=(2*mod[i+1][1])%(count-1);
      else
        mod[i][1]=0;
    }
    if(x[i]=='1'){
      num[0]=(num[0]+mod[i][0])%(count+1);
      if(count>1)
        num[1]=(num[1]+mod[i][1])%(count-1);
    }
  }
  for(i=0;i<n;i++){
    int ans;
    if(x[i]=='1' && count-1==0)
      ans=0;
    else if(x[i]=='1')
      ans=popcount[(num[1]-mod[i][1]+count-1)%(count-1)]+1;
    else
      ans=popcount[(num[0]+mod[i][0])%(count+1)]+1;
    printf("%d\n",ans);
  }
  return 0;
}

