        let mut sum_a: Vec<usize> = Vec::new();
        if a[0] > k {
            sum_a
        } else {
            sum_a.push(a[0]);
            for i in 1..n {
                let xx = sum_a[i-1]+a[i];
                if xx > k {
                    break;
                }
                sum_a.push(xx);
            }
            sum_a.reverse();
            sum_a
        }
    };

    let sum_b = {
        let mut sum_b: Vec<usize> = Vec::new();
        if b[0] > k {
            sum_b
        } else {
            sum_b.push(b[0]);
            for i in 1..m {
                let xx = sum_b[i-1]+b[i];
                if xx > k {
                    break;
                }
                sum_b.push(xx);
            }
            sum_b
        }
    };

    let len_a = sum_a.len();
    let len_b = sum_b.len();
    let mut ans = {
        if a[0] > k {
            0
        } else {
