      long[] Atotal = new long[N+1];
      long[] Btotal = new long[M+1];
      int Amax = -1;
      int Bmax = -1;

      Atotal[0] = 0;
      for(int i = 0; i < N+1; i++){
        if(i < N){
          A[i] = sc.nextInt();
        }
        if(i > 0){
          Atotal[i] = Atotal[i-1] + A[i-1];
          if(Amax == -1 && Atotal[i] > K){
            Amax = i-1;
          }
        }
      }
      if(Amax == -1){
        Amax = N;
      }

      Btotal[0] = 0;
      B[0] = sc.nextInt();
      for(int i = 1; i < M+1; i++){
        if(i < M){
          B[i] = sc.nextInt();
        }
        if(i > 0){
          Btotal[i] = Btotal[i-1] + B[i-1];
          if(Bmax == -1 && Btotal[i] > K){
            Bmax = i-1;
          }
        }
      }
      if(Bmax == -1){
        Bmax = M;
      }

      // 全部読み切れるか
      int result = 0;
      if(Atotal[N] + Btotal[M] <= K){
        result = N+M;
      }else if(Amax == 0 && Bmax == 0){
        // 1冊も読めないか
