        int totalMax = 0;
        if(Amax > Bmax){
          totalMax = Amax;
        }else{
          totalMax = Bmax;
        }

        for(int i = 0; i <= Amax; i++){
          for(int j = totalMax - i; j <= Bmax; j++){
            totalTime = Atotal[i] + Btotal[j];
            if(totalTime <= K){
              //System.out.println(i + " " + j + " " + totalTime);

              int max = i+j;
              if(totalMax < max){
                totalMax = max;
              }
            }else{
              break;
            }
          }
        }
        result = totalMax;
      }

      // 出力
