// 二分探索で目的の値より大きいインデックスを返す
func upperBound(list []int64, n int64) int64 {
	var l int64 = 0
	var r int64 = int64(len(list) - 1)
	for l <= r {
		var mid int64 = l + (r-l)/2
		if list[mid] <= n {
			l = mid + 1
		} else {
			r = mid - 1
		}
	}
	return l
}

func main() {
	list := getStdinIntArr64()
	N := list[0]
	M := list[1]
	K := list[2]
	A := getStdinIntArr64()
	B := getStdinIntArr64()
	Asum := make([]int64, N+1)
	Bsum := make([]int64, M+1)

	var i int64 = 0
	var ans int64 = 0

	for i = 0; i < N; i++ {
		Asum[i+1] = Asum[i] + A[i]
	}
	for i = 0; i < M; i++ {
		Bsum[i+1] = Bsum[i] + B[i]
	}

	var apos int64 = 0
	for ; apos <= N; apos++ {
		if Asum[apos] > K {
			break
		}
		if M > 0 {
			var bpos int64 = upperBound(Bsum, K-Asum[apos])
			if bpos != 0 {
				bpos--
			}
			if apos+bpos > ans {
				ans = apos + bpos
			}
		}
	}
	fmt.Printf("%d\n", ans)
}

