		String T = sc.next();
		sc.close();

		if(N < M) {
			int cap = N;
			N = M;
			M = cap;
			String cap2 = S;
			S = T;
			T = cap2;
		}

		if(S.equals(T)) {
			System.out.println(N);
		} else if(S.charAt(0) != T.charAt(0)){
			System.out.println("-1");
		} else if(M == 1) {
			System.out.println(N);
		} else if(N % M == 0){
			boolean flag = true;
			for(int i = 0;i < M;++i) {
				if(S.charAt(i*(N/M)) != T.charAt(i)) {
					flag = false;
					break;
				}
			}
