import java.util.*;
import java.io.*;

class Main {



  public static void main(String[] args) {
    Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
    int INF = (int) 1e9 + 7;

    int N = in.nextInt();
    int K = in.nextInt();
    int[] a = new int[N];
    for (int i = 0; i < N; i++) {
      a[i] = in.nextInt();
    }

    int[] dp = new int[K + 1];
    dp[0] = 1;
    // Arrays.fill(dp[0], 1);
    for (int child = 0; child < N; child++) {
      int[] tmp = new int[K + 1];
      for (int used = K; used >= 0; used--) {

        // pre + (j - a[i - 1] ... j)
        // int pre = (dp[i - 1][j] - (j - a[i - 1] <= 0 ? 0 : dp[i - 1][j - a[i - 1] - 1]));
        // if (pre < 0) {pre += INF;}
        // dp[i][j] = (j == 0 ? 0 : dp[i][j - 1]) + pre;
        // if (dp[i][j] >= INF) {dp[i][j] -= INF;}

        int delta = dp[used];
        int L = used + 1;
        int R = used + Math.min(a[child], K - used);

        if (L <= R) {
          tmp[L] += delta;
          if (tmp[L] >= INF) tmp[L] -= INF;
          if (R + 1 <= K) {
            tmp[R + 1] -= delta;
            if (tmp[L] < 0) tmp[L] += INF;
          }
        }

        // for (int here = 1; here <=  Math.min(a[child], K - used); here++) {
        //   dp[used + here] += dp[used];
        //   if (dp[used] >= INF) {dp[used] -= INF;}
        // }
      }

      int prefix = 0;
      for (int i = 0; i <= K; i++) {
        prefix += tmp[i];
        if (prefix >= INF) prefix -= INF;
        if (prefix < 0) prefix += INF;
        dp[i] += prefix;
        if (dp[i] >= INF) dp[i] -= INF;
        if (dp[i] < 0) dp[i] += INF;

      }
    }

    // int res = dp[N][K] - (K == 0 ? 0 : dp[N][K - 1]);
    System.out.println(dp[K]);
  }

}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int K = sc.nextInt();
    List<List<Integer>> t = new ArrayList<>();
    for (int i = 0; i < N; i++) {
      t.add(new ArrayList<>());
    }
    for (int i = 0; i < N-1; i++) {
      int a = sc.nextInt();
      a--;
      int b = sc.nextInt();
      b--;
      t.get(a).add(b);
      t.get(b).add(a);
    }

    if (N == 1) {
      System.out.println(K);
      return;
    }

    int[] child = new int[N];
    for (int i = 0; i < N; i++) {
      child[i] = -1;
    }
    LinkedList<Integer> q = new LinkedList<>();
    q.offer(0);
    while (!q.isEmpty()) {
      int p = q.poll();
      child[p] = 0;
      for (int c : t.get(p)) {
        if (child[c] == -1) {
          child[p]++;
          q.offer(c);
        }
      }
      if ((p == 0 && child[0] > K-1)
         || (p > 0 && child[p] > K-2)) {
        System.out.println(0);
        return;
      }
    }
    int[] power = new int[K+1];
    power[K] = 1;
    power[K-1]--;

    power[K-1]++;
    power[K-1-child[0]]--;

    for (int i = 1; i < N; i++) {
      if (child[i] > 0) {
        power[K-2]++;
        power[K-2-child[i]]--;
      }
    }

    //System.out.println(Arrays.toString(power));

    int num = 0;
    for (int i = K; i >=0; i--) {
      num += power[i];
      power[i] = num;
    }

    long ans = 1;
    for (int i = 2; i <= K; i++) {
      while (power[i]-- > 0) {
        ans *= i;
        ans %= 1_000_000_007;
      }
    }

    //System.out.println(Arrays.toString(child));
    //System.out.println(Arrays.toString(power));
    System.out.println(ans);
  }
}

