fn main() {
  input! {
    n: usize,
    m: usize,
  }

  if m % n == 0 {
    println!("{}", m / n);
    return
  }

  let mut map: HashMap<usize, bool> = HashMap::new();
  let mut i = 2;
  let mut v = m;
  while i * i <= m && 0 < v {
    if v % i == 0 {
      map.insert(i, true);
      v /= i;
    } else {
      i += 1;
    }
  }

  if map.keys().len() == 0 {
    println!("1");
    return
  }

  let mut v = m / n;
  while m % v != 0 || (m / v) < n {
    v -= 1;
  }
  println!("{}", v);
}

