macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

#[allow(unused_mut)]
#[allow(non_snake_case)]
fn main() {
    input!{
        N: usize,
        M: usize,
        edges: [(usize1, usize1); M],
    }

    let mut union_find = UnionFind {
        parent: (0..N).collect(),
        size: vec![1; N],
    };


    let mut closed = N*(N-1)/2;
    let mut output: Vec<usize> = Vec::with_capacity(M);

    for (a, b) in edges.into_iter().rev() {
        output.push(closed);
        let root_a = union_find.root(a);
        let root_b = union_find.root(b);
        if root_a != root_b {
            closed -= union_find.size[root_b] * union_find.size[root_a];
            union_find.parent[root_a] = root_b;
            union_find.size[root_b] += union_find.size[root_a];
        }
    }

    for c in output.into_iter().rev() {
        println!("{}", c);
    }
}

struct UnionFind {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl UnionFind {
    fn root(&mut self, v: usize) -> usize {
        let mut parent_v = self.parent[v];
        loop {
            if parent_v == self.parent[parent_v] {
                break;
            } else {
                parent_v = self.parent[parent_v];
            }
        }
        self.parent[v] = parent_v;
        parent_v
    }
}

